const form='https://docs.google.com/forms/d/e/1FAIpQLScFUxfaVQmYZxskN-9nhjsCRx7HdjH-aqi5wPaeU3Z9AOwdEg/viewform';
document.querySelectorAll('.form-link').forEach(a=>{a.href=form;a.target='_blank';a.rel='noopener noreferrer';a.setAttribute('aria-label',a.textContent.trim()+' (새 탭에서 구글 폼 열기)')});

const reduce=matchMedia('(prefers-reduced-motion: reduce)').matches;
const progress=document.createElement('div');progress.className='scroll-progress';progress.setAttribute('aria-hidden','true');document.body.prepend(progress);

if(!reduce){
  document.documentElement.classList.add('motion');
  document.querySelectorAll('a[href^="#"]').forEach(link=>link.addEventListener('click',event=>{const id=link.getAttribute('href');const target=id==='#'?document.body:document.querySelector(id);if(!target)return;event.preventDefault();const header=document.querySelector('header');const start=scrollY;const destination=Math.max(0,target.getBoundingClientRect().top+start-header.offsetHeight);const distance=destination-start;const duration=Math.min(1100,Math.max(550,Math.abs(distance)*.45));const began=performance.now();const ease=t=>1-Math.pow(1-t,4);function move(now){const t=Math.min(1,(now-began)/duration);scrollTo(0,start+distance*ease(t));if(t<1)requestAnimationFrame(move)}requestAnimationFrame(move)}));
  if('IntersectionObserver' in window){const observer=new IntersectionObserver(entries=>entries.forEach(entry=>{if(entry.isIntersecting){entry.target.classList.add('visible');observer.unobserve(entry.target)}}),{threshold:.14,rootMargin:'0px 0px -7%'});document.querySelectorAll('.reveal').forEach((el,index)=>{el.style.setProperty('--reveal-delay',`${Math.min(index%4,2)*70}ms`);observer.observe(el)})}
}

let ticking=false;function updateScroll(){const y=scrollY;const max=document.documentElement.scrollHeight-innerHeight;progress.style.transform=`scaleX(${max>0?Math.min(1,y/max):0})`;document.querySelector('header').classList.toggle('scrolled',y>24);if(!reduce){const product=document.querySelector('.product');if(product&&y<900)product.style.transform=`scale(${1.03+Math.min(y,800)*.0001}) translate3d(0,${Math.min(y,800)*.028}px,0)`;const statement=document.querySelector('.statement-bottom .mark');if(statement){const rect=statement.getBoundingClientRect();if(rect.top<innerHeight&&rect.bottom>0)statement.style.transform=`rotate(${(innerHeight-rect.top)*.018}deg)`}const contact=document.querySelector('.contact-symbol');if(contact){const rect=contact.getBoundingClientRect();if(rect.top<innerHeight&&rect.bottom>0)contact.style.transform=`translate3d(0,${(innerHeight-rect.top)*-.035}px,0) rotate(-20deg)`}}ticking=false}addEventListener('scroll',()=>{if(!ticking){ticking=true;requestAnimationFrame(updateScroll)}},{passive:true});updateScroll();

const data=[['BEAUTY & LIFESTYLE','취향이 만나는 곳에서','새롭게 발견되는 브랜드.','#F1EB9D'],['EXPERIENCE & DISCOVERY','직접 경험하는 순간','더 깊이 전해지는 가치.','#e5e9df'],['EVERYDAY & DESTINATION','일상과 여행 사이','자연스럽게 만나는 뷰티.','#e9e5d8'],['LOCAL TO GLOBAL','더 넓은 시장을 향해','경계 없이 이어지는 가능성.','#dce5e7']];
const panel=document.querySelector('.channel-display');panel.id='channel-info';panel.setAttribute('role','tabpanel');panel.setAttribute('aria-labelledby','tab-0');const tabs=[...document.querySelectorAll('[data-channel]')];
function select(i){tabs.forEach((b,j)=>{b.setAttribute('aria-selected',String(i===j));b.tabIndex=i===j?0:-1});const d=data[i];document.querySelector('#channel-en').textContent=d[0];document.querySelector('#channel-caption').textContent=d[1];document.querySelector('#channel-title').textContent=d[2];document.querySelector('#channel-count').textContent=`0${i+1} — 04`;panel.style.background=d[3];panel.setAttribute('aria-labelledby',`tab-${i}`);document.querySelector('.channel-symbol').style.transform=`rotate(${-15+i*45}deg) scale(1.04)`}
tabs.forEach((b,i)=>{b.addEventListener('click',()=>select(i));b.addEventListener('keydown',e=>{let j=i;if(e.key==='ArrowDown'||e.key==='ArrowRight')j=(i+1)%4;else if(e.key==='ArrowUp'||e.key==='ArrowLeft')j=(i+3)%4;else if(e.key==='Home')j=0;else if(e.key==='End')j=3;else return;e.preventDefault();select(j);tabs[j].focus()})});
